// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

public class TripleStoreAlignedSortResetTest {

	@Test
	public void testStoreTriplesAlignedResetsToMainOrderBeforeBeneficialTransition(@TempDir File dataDir)
			throws Exception {
		assertAlignedInputOrder(dataDir, false);
	}

	@Test
	public void testStoreTriplesAlignedResetsSparseMainOrderBeforeBeneficialTransition(@TempDir File dataDir)
			throws Exception {
		assertAlignedInputOrder(dataDir, true);
	}

	private static void assertAlignedInputOrder(File dataDir, boolean sparse) throws Exception {
		File storeDir = new File(dataDir, sparse ? "aligned-sparse-reset-store" : "aligned-reset-store");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,psoc,ospc");
		long[] subjects = { 1, 1, 2, 2 };
		long[] predicates = { 1, 2, 1, 2 };
		long[] objects = { 2, 1, 1, 2 };
		long[] contexts = { 0, 0, 0, 0 };
		long[][] original = { subjects.clone(), predicates.clone(), objects.clone(), contexts.clone() };
		List<List<Long>> expected = LmdbPersistentMutationBatchObservation.rows(subjects, predicates, objects,
				contexts, subjects.length);
		List<Integer> expectedCallbacks = sparse ? List.of(1, 2, 3) : List.of(0, 1, 2, 3);

		try (TripleStore store = new TripleStore(storeDir, config, null)) {
			if (sparse) {
				store.startTransaction();
				store.storeTriple(subjects[0], predicates[0], objects[0], contexts[0], true);
				store.commit();
			}

			store.startTransaction();
			List<Integer> added = new ArrayList<>();
			var observation = LmdbPersistentMutationBatchObservation.observe(store);
			try (observation) {
				store.storeTriplesAligned(subjects, predicates, objects, contexts, subjects.length, true,
						observation.callbacks(added::add));
			}
			observation.assertBatch(expectedCallbacks.size(), 2, true);
			assertSame(Thread.currentThread(), observation.writerThread());
			assertEquals(expectedCallbacks, observation.callbackIndices());
			assertEquals(expectedCallbacks, added, "only newly accepted input indices escape, in caller order");
			assertArrayEquals(original[0], subjects);
			assertArrayEquals(original[1], predicates);
			assertArrayEquals(original[2], objects);
			assertArrayEquals(original[3], contexts);
			store.commit();
			LmdbPersistentMutationBatchObservation.assertDirections(store, expected, List.of());
			LmdbPersistentMutationBatchObservation.assertOrders(store, List.of("spoc", "psoc", "ospc"), expected,
					List.of());

			store.startTransaction();
			var duplicateObservation = LmdbPersistentMutationBatchObservation.observe(store);
			try (duplicateObservation) {
				store.storeTriplesAligned(subjects, predicates, objects, contexts, subjects.length, true,
						duplicateObservation.callbacks(null));
			}
			duplicateObservation.assertBatch(0, 2, true);
			assertEquals(List.of(), duplicateObservation.callbackIndices(), "duplicate rows never notify twice");
			store.commit();
		}

		try (TripleStore reopened = new TripleStore(storeDir, config, null)) {
			LmdbPersistentMutationBatchObservation.assertDirections(reopened, expected, List.of());
			LmdbPersistentMutationBatchObservation.assertOrders(reopened, List.of("spoc", "psoc", "ospc"), expected,
					List.of());
		}
	}
}
